I will implement the comparison logic.
Assumptions:
- Degree Level must be exactly 'Masters' or 'PhD' and Degree Field must be one of ['Biology','Biochemistry','Biotechnology'].
- Programming Lang must be exactly one of ['C++','C#','Fortran'].
- Second Language must be non-empty.
Python
import pandas as pd

df = pd.read_excel('./working_dir/Applicants.xlsx')

valid_fields = {'Biology','Biochemistry','Biotechnology'}
valid_levels = {'Masters','PhD'}
valid_langs = {'C++','C#','Fortran'}

def missing_count(row):
    m = 0
    if (row['Degree Level'] not in valid_levels) or (row['Degree Field'] not in valid_fields):
        m += 1
    if pd.to_numeric(row['Experience (Years)'], errors='coerce') < 3:
        m += 1
    if str(row['Lab Trained (Y/N)']).strip().upper() != 'Y':
        m += 1
    if pd.to_numeric(row['Publications'], errors='coerce') < 3:
        m += 1
    if str(row['Citizen (Y/N)']).strip().upper() != 'Y':
        m += 1
    # Exact match for programming language
    if str(row['Programming Lang']).strip() not in valid_langs:
        m += 1
    # Second language must be present
    val = str(row['Second Language'])
    if (pd.isna(row['Second Language'])) or (val.strip() == ''):
        m += 1
    return m

counts = df.apply(missing_count, axis=1)
result = (counts == 1).sum()
print('Number of applicants missing exactly one qualification:', int(result))
